// DefaultBaseURL is the Personal API endpoint.
const DefaultBaseURL = "https://personal.connectapi.garmin.com"

const (
	tokenPath    = "/personalapitoken-service/personal-api/personal-api-key/token"
	searchPath   = "/activitylist-service/activities/search/activities"
	downloadPath = "/download-service/files/activity/"

	// tokenRefreshWindow renews the token an hour before it expires, like
	// Garmin's own client.
	tokenRefreshWindow = time.Hour
	// tokenFallbackLifetime applies if the token's expiry cannot be read.
	tokenFallbackLifetime = 24 * time.Hour

	pageSize = 100
	// maxPages bounds the activity listing (100,000 activities).
	maxPages = 1000
	// maxDownloadSize bounds a downloaded original file (ZIP).
	maxDownloadSize = 128 << 20
)

var (
	// ErrAuthRequired means the API key is missing, invalid, revoked or expired.
	ErrAuthRequired = errors.New("Garmin-API-Schlüssel fehlt, ist ungültig oder abgelaufen")
	// ErrRateLimited means Garmin throttles requests; retry much later.
	ErrRateLimited = errors.New("Garmin Connect begrenzt die Anfragen, später erneut versuchen")
	// ErrNoFile means the activity has no downloadable original FIT file
	// (manual entries, GPX/TCX uploads from other apps).
	ErrNoFile = errors.New("keine Original-FIT-Datei vorhanden")
)

// Activity is one entry of the activity list.
type Activity struct {
	ID           int64  `json:"activityId"`
	Name         string `json:"activityName"`
	StartTimeGMT string `json:"startTimeGMT"`
	DeviceID     int64  `json:"deviceId"`
	ActivityType struct {
		TypeKey string `json:"typeKey"`
	} `json:"activityType"`
}

// Client calls the Personal API with an API key.
type Client struct {
	APIKey  string
	BaseURL string
	HTTP    *http.Client
	Logger  *slog.Logger
	now     func() time.Time

	mu      sync.Mutex
	token   string
	expires time.Time
}

// NewClient creates a client for the given API key.
func NewClient(apiKey string, logger *slog.Logger) *Client {
	return &Client{APIKey: strings.TrimSpace(apiKey), BaseURL: DefaultBaseURL, Logger: logger}
}

// Configured reports whether an API key is set.
func (c *Client) Configured() bool { return c != nil && c.APIKey != "" }

func (c *Client) http() *http.Client {
	if c.HTTP != nil {
		return c.HTTP
	}
	return &http.Client{Timeout: 60 * time.Second}
}

func (c *Client) clock() time.Time {
	if c.now != nil {
		return c.now()
	}
	return time.Now()
}

func (c *Client) logger() *slog.Logger {
	if c.Logger != nil {
		return c.Logger
	}
	return slog.New(slog.DiscardHandler)
}

// bearer returns a valid token, requesting a new one if needed.
func (c *Client) bearer(ctx context.Context, force bool) (string, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if !force && c.token != "" && c.expires.Sub(c.clock()) > tokenRefreshWindow {
		return c.token, nil
	}
	if !c.Configured() {
		return "", ErrAuthRequired
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.BaseURL+tokenPath, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Accept", "*/*")
	req.Header.Set("Authorization", "ApiKey "+c.APIKey)
	resp, err := c.http().Do(req)
	if err != nil {
		return "", fmt.Errorf("garmin token: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	if err := statusError(resp.StatusCode, "token"); err != nil {
		return "", err
	}
	token := strings.TrimSpace(string(body))
	if token == "" || strings.ContainsAny(token, " \n\t") {
		return "", errors.New("garmin token: unexpected response")
	}
	c.token = token
	c.expires = tokenExpiry(token, c.clock())
	c.logger().Debug("garmin token obtained", "expires", c.expires)
	return token, nil
}

// tokenExpiry reads the exp claim of a JWT without verifying it (the token
// is only passed back to Garmin).
func tokenExpiry(token string, now time.Time) time.Time {
	fallback := now.Add(tokenFallbackLifetime)
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return fallback
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return fallback
	}
	var claims struct {
		Exp int64 `json:"exp"`
	}
	if json.Unmarshal(payload, &claims) != nil || claims.Exp == 0 {
		return fallback
	}
	return time.Unix(claims.Exp, 0)
}

func statusError(code int, what string) error {
	switch {
	case code >= 200 && code < 300:
		return nil
	case code == http.StatusUnauthorized || code == http.StatusForbidden:
		return ErrAuthRequired
	case code == http.StatusTooManyRequests:
		return ErrRateLimited
	case code == http.StatusNotFound:
		return ErrNoFile
	}
	return fmt.Errorf("garmin %s: HTTP %d", what, code)
}

// get performs an authenticated GET. A 401 renews the token once, since the
// cached token may have been revoked together with an old key.
func (c *Client) get(ctx context.Context, path string, query url.Values, limit int64) ([]byte, error) {
	for attempt := 0; ; attempt++ {
		token, err := c.bearer(ctx, attempt > 0)
		if err != nil {
			return nil, err
		}
		u := c.BaseURL + path
		if len(query) > 0 {
			u += "?" + query.Encode()
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
		if err != nil {
			return nil, err
		}
		req.Header.Set("Authorization", "Bearer "+token)
		resp, err := c.http().Do(req)
		if err != nil {
			return nil, fmt.Errorf("garmin %s: %w", path, err)
		}
		body, readErr := io.ReadAll(io.LimitReader(resp.Body, limit+1))
		resp.Body.Close()
		if resp.StatusCode == http.StatusUnauthorized && attempt == 0 {
			continue
		}
		if err := statusError(resp.StatusCode, path); err != nil {
			return nil, err
		}
		if readErr != nil {
			return nil, readErr
		}
		if int64(len(body)) > limit {
			return nil, fmt.Errorf("garmin %s: response larger than %d bytes", path, limit)
		}
		return body, nil
	}
}

// Activities lists all activities starting on or after since, newest first.
func (c *Client) Activities(ctx context.Context, since time.Time) ([]Activity, error) {
	var all []Activity
	for page := 0; page < maxPages; page++ {
		q := url.Values{
			"start":     {strconv.Itoa(page * pageSize)},
			"limit":     {strconv.Itoa(pageSize)},
			"startDate": {since.Format(time.DateOnly)},
		}
		body, err := c.get(ctx, searchPath, q, 16<<20)
		if err != nil {
			return nil, err
		}
		var batch []Activity
		if err := json.Unmarshal(body, &batch); err != nil {
			return nil, fmt.Errorf("garmin activities: %w", err)
		}
		all = append(all, batch...)
		if len(batch) < pageSize {
			return all, nil
		}
	}
	return nil, fmt.Errorf("garmin activities: more than %d pages", maxPages)
}

// DownloadFIT returns the original FIT file of an activity. Garmin wraps it
// in a ZIP; non-FIT originals yield ErrNoFile.
func (c *Client) DownloadFIT(ctx context.Context, id int64) ([]byte, error) {
	body, err := c.get(ctx, downloadPath+strconv.FormatInt(id, 10), nil, maxDownloadSize)
	if err != nil {
		return nil, err
	}
	return extractFIT(body)
}

func isFIT(b []byte) bool { return len(b) >= 12 && string(b[8:12]) == ".FIT" }

func extractFIT(payload []byte) ([]byte, error) {
	if isFIT(payload) {
		return payload, nil
	}
	zr, err := zip.NewReader(bytes.NewReader(payload), int64(len(payload)))
	if err != nil {
		return nil, ErrNoFile
	}
	for _, f := range zr.File {
		if !strings.EqualFold(pathExt(f.Name), ".fit") || f.UncompressedSize64 > maxDownloadSize {
			continue
		}
		rc, err := f.Open()
		if err != nil {
			return nil, err
		}
		data, err := io.ReadAll(io.LimitReader(rc, maxDownloadSize))
		rc.Close()
		if err != nil {
			return nil, err
		}
		if isFIT(data) {
			return data, nil
		}
	}
	return nil, ErrNoFile
}

func pathExt(name string) string {
	if i := strings.LastIndexByte(name, '.'); i >= 0 {
		return name[i:]
	}
	return ""
}
